from pathlib import Path
from collections import Counter
import json,re

O=Path(__file__).resolve().parents[1]
B={b['id']:b for b in json.loads((O/'_source/blocks.json').read_text())}
edits=[]
def edit(i,problem,reason,benefit,text):
    bid=f'B{i:04d}';b=B[bid]
    assert 234<i<329 and b['kind']=='p' and not b['style_name'].startswith('heading')
    assert text!=b['text']
    assert re.findall(r'\[\d+\]',text)==re.findall(r'\[\d+\]',b['text']),(bid,'citations')
    nums=lambda t:Counter(re.findall(r'\d+(?:\.\d+)?',t))
    assert nums(text)==nums(b['text']),(bid,'numbers',nums(text)-nums(b['text']),nums(b['text'])-nums(text))
    edits.append({'block_id':bid,'old_text':b['text'],'new_text':text,'problem':problem,'reason':reason,'benefit':benefit})

edit(235,'章首同时重复研究背景、罗列技术名称和预告章节，后半段近似目录复述。','把共同需要回答的问题放在前面，再说明本章如何支撑后续方法；保留原有技术范围与章节分工。','读者先知道本章的阅读目的，再理解各类基础概念之间的关系。','训练中的监督保持与预测图的结构修正，都需要明确组件和关系如何表示、模型如何学习，以及预测结果如何评价。本章围绕这些共同问题，统一论辩对象的规范身份，介绍生成建模、参数高效适配、数据增强与一致性学习，并说明候选评分、结构化决策和评价方法。公共数据使用原则与阶段接口为后续实验提供统一条件，具体增强算法和修正算法分别在第三、四章展开。')
edit(238,'“完成这些预测”的指代略宽，端到端输入条件与允许的多步骤流程挤在同一句解释中。','先区分定位和分类两项操作，再分别说明端到端的输入限制及流程范围。','读者可明确端到端指向输入输出条件，不会将其误解为必须只执行一次生成。','论辩挖掘以未提供金标结构的文档为输入，输出论辩组件及其关系。组件识别确定相关文字在原文中的位置，组件分类判断其论辩角色。本文要求模型从原文完成组件与关系预测，不将测试集金标组件作为输入。在这一端到端设定下，系统可以依次执行生成、候选选择和预测修正等多个计算步骤。')
edit(242,'分词差异、字符边界和更换分词器的处理原则分别陈述，三者的主从关系尚可更紧密。','以“派生表示不改变规范边界”为中心，连接两种分词的用途和更换分词器时的操作。','读者能够区分可更换的切分方式与必须保留的评价对象。','评价分词和模型分词都是原文的派生表示：评价token用于统一评价处理与跨度索引，模型子词用于构造神经网络输入，二者均通过字符偏移映射回原文。切分方式可以不同，组件的规范字符边界仍须保持一致。因此，更换分词器时应重新建立映射，并保留原有金标组件的定义。')
edit(247,'原生任务差异、结论角色和跨域映射在一段内切换，读者需要自行补出它们与身份保持的关系。','保留例子，以“原生类型不随方法用途改变”为承接，明确结论角色只服务于增强和模块选择。','区分任务标签、方法内部角色与附录映射，避免把不同层次的分类混为一谈。','两种任务的差异由原生标注及相应研究确定[2][3][46]。例如，CDCP关系若包含两个源组件，漏掉任意一个就不再匹配该完整关系。第三章引入的结论角色仅用于选择增强中心或触发相应模块，CDCP原生类型仍保持不变，不改写为Claim或Premise。域内实验分别按两种任务评价，附录中的粗粒度跨域映射也不改变上述定义。')
edit(249,'“词中边界尤其需要保留这一差别”的指代需回看前句，字符身份问题可以更直接引出。','先说明字符坐标的用途，再指出token外包范围为何不足以区分对象。','为后面的字符残差公式提供明确动机，降低定义之间的跳跃。','规范字符坐标用于确定评价对象在原文中的准确位置。若仅用评价token的起止位置和类型标识组件，具有相同token外包范围、但字符边界不同的片段就可能被合并。组件边界落在词内时，仅靠token索引尤其难以保留这种差异。')
edit(252,'残差恢复、异常记录、子词映射和提示位置补偿连续出现，条件与操作的对应关系较密集。','按恢复能力、异常处理、模型位置映射的顺序组织句子，保留各项坐标规则。','读者可顺着坐标转换过程理解每个例外应如何处理。','派生记录 (s,u,ρL,ρR) 因而可以恢复原字符区间，仅有 (s,u) 则通常不能。若协议保留首尾空白，残差须按有符号坐标差保存；若找不到可对应的token，则单独记录异常，不补造跨度。模型子词通过offset mapping与字符区间对应，聊天模板或连续提示引入的位置偏移另行补偿，不计入原文字符坐标。')
edit(253,'案例介绍中的“标注事实”“身份区别”较抽象，可直接说明真实对象和构造对照的区别。','紧贴表中边界现象说明保留理由，并把构造对照的用途与性质放在同一句。','读者无需到表后再判断哪行来自原始标注、哪行只是说明性对照。','表2-2以AAEC原生文档essay098的T6组件为例。原标注在responsible的最后一个字母之前结束，本文保留这一边界，不自动补全单词。表中另构造了一个扩展至完整单词的片段，用于说明两种边界对应不同对象；该片段不是另一条金标。')
edit(257,'“均使用这一身份”指向不够具体，规范键的定义和实际用途之间还可连接得更清楚。','明确各处理环节使用规范键识别对象，再解释显示编号不参与身份判断。','把抽象身份定义落实到去重、缓存、记录和评价中的实际作用。','组件规范键由式（2-1）的四个字段确定。关系键在此基础上包含完整端点和关系标签，多前提关系的源端则保存按规范键排序的完整组件集合。候选去重、评分缓存、修改记录和严格匹配均使用规范键识别对象。T3、T4等显示编号仅供文档内部引用，重新编号既不产生新对象，也不计为一次编辑。')
edit(258,'旧关系身份与评分不能沿用的原因分散在前后句，序列化规则也需和异常处理更明确地区分。','将组件键变化与关系重判直接连接，随后单独说明序列化及缺失端点的处理。','读者能够理解关系重判的依据，同时区分正常表示规则和异常出口。','组件边界或类型改变时，规范键随之变化，关联关系须根据新端点重新判断。因此，即使关系的显示编号未变，也不能直接沿用旧关系的身份或评分。序列化统一使用sources字段表示源集合，并保留AAEC stance属性。缺失端点记为异常，不通过补造组件或关系恢复结构。')
edit(259,'“不表示两侧字符键相等”与后续坐标更新、审核规则之间的关联可以更加直接。','先界定对应映射的职责，再按位置更新和监督审核两个操作展开。','明确“能够对应”与“键相同”“可以参与学习”是不同判断。','原文与增强视图属于不同文本版本。第三章的映射 φ 描述槽位回填后两个版本之间的组件对应，而不要求两侧字符键相等。改写改变文本长度时，所有受影响组件的字符位置均须更新；更新后哪些组件和关系可参与学习，再依据各自的审核状态确定。')
edit(260,'“放在同一框架下”没有说明框架具体区分什么，容易成为抽象过渡。','直接列出需要区分的对象定义、候选范围、输出、评分和评价。','表格在进入前已有明确阅读线索，各层次之间的区别更容易定位。','结构化预测涉及对象定义、候选范围、实际输出、对象评分和结果评价。表2-3分别说明这五个层次，区分“对象可被选择”“对象得分较高”与“对象预测正确”三个判断。')
edit(263,'“制造合法性”的表述偏论辩，规范定义与数据处理原则可写得更平实。','按基本合法性、语料特定约束及测试标注处理三个层次陈述，保留全部约束边界。','合法结构的定义更便于查阅，语气从防御式说明转为明确的协议说明。','合法结构集合记为 GA，其中 A 为固定的语料协议。基本条件包括跨度位于原文、类型与关系标签有效以及端点存在；重叠、嵌套和拓扑限制则由具体语料确定。本文不预设所有论辩文本都满足树结构或无环条件，也不因测试标注不符合预设规则而将其删除。')

edit(266,'“对值向量进行加权”未将聚合操作说完整，公式引入还可更贴近计算过程。','明确查询和键决定权重、值向量按权重求和，再引入已有公式。','读者能先把握注意力的操作链，再阅读矩阵表达式；未增加新的技术机制。','Transformer通过注意力机制聚合不同位置的信息，是本文所用骨干模型的基础[30][31]。注意力先根据查询与键的相似程度计算权重，再对值向量加权求和。缩放点积注意力表示为')
edit(268,'局部符号说明、多头计算和因果限制放在一起，自回归可用信息的表述存在重复。','保留符号区别，将多头注意力和自回归解码各自的作用分开陈述。','避免将表示子空间的分工与生成顺序的约束混在一起。','其中，Q、K、V 分别为查询、键和值矩阵，dk 为键向量维度。此处的 V 仅用于注意力计算，与第四章的组件候选集合不同。多头注意力在不同表示子空间中计算信息关联。自回归解码则限制当前位置仅能使用输入和已经生成的输出，不能访问后续输出。')
edit(272,'“训练时利用……测试时则使用……”未突出前缀来源这一比较维度，后半段的评价对象也可更具体。','以训练和测试所用前缀为主线，再说明统一生成接口与完整对象正确性之间的关系。','读者可同时理解生成损失的计算条件及序列概率的解释范围。','训练时使用当前位置之前的金标符号作为前缀，计算下一输出符号的损失；测试时则使用模型此前已生成的符号。生成式论辩挖掘将多个子任务组织为统一输出[7]。不过，序列概率还受输出长度、字段次序等因素影响，不能直接替代对完整论辩对象的正确性判断。')
edit(276,'“保留基础权重”“提供可训练接口”较抽象，LoRA与连续提示的分工可直接说明。','使用“更新”与“冻结”明确参数状态，并用权重增量和输入条件说明两种适配方式的区别。','减少读者对哪些参数可训练的猜测，保持与前文LoRA定义一致。','其中，r 为低秩维度，α 为缩放系数。训练主要更新增量矩阵，基础权重 W0 保持冻结。连续提示通过学习提示向量表达任务条件，也是参数高效适配方式[33]。二者分别调整权重增量和输入条件，为下游任务引入可训练参数。')
edit(277,'主骨干、补充骨干、共享资源和历史记录在长段中连续切换，代词“后两者”增加回溯。','按主实验用途、补充验证分工、共享内容与独立模块、历史记录依次解释。','明确各骨干承担什么实验，以及“共享增强”并不表示各模型共用全部模块。','本文以Qwen3.5-9B为主骨干[51]，统一配置ICIC/MCR-BR基线T0、本文T1及外部适配对照。完整消融与错误分析在9B上开展；Qwen3.5-4B用于检查较小骨干下的适用性，Qwen2.5-7B-Instruct用于衔接已有方法并进行跨版本验证[53][54]。两种补充骨干使用9B增强与审核流程得到的共享视图，抽取器、评分器和提案器则各自配置。附录E保留原发表数值，更新后的实验数据不替换历史记录。')
edit(279,'“样本包含多类监督”与“分别判断”之间略显概括，可把局部语义变化影响哪些标签说清楚。','将通顺性与监督保持作为两个独立判断，具体承接组件位置、类型与关系。','读者更容易理解后文为什么需要逐因素审核，而不是整篇文本一次判定。','数据增强通过改变输入表达扩充训练样本。语言模型生成的改写即使通顺，也不意味着原有标注可以全部沿用[15][35]。论辩挖掘的监督包括组件位置、类型和关系，局部语义变化可能仅使其中部分标签失效。因此，增强文本的通顺性与各项监督能否保留，需要分别判断。')
edit(282,'“将这一量加入学习目标”指代较弱，监督屏蔽条件也可直接对应到操作。','明确所加的是散度项，并以“未确认标签不参与相应项”说明掩码用途。','连接公式与训练行为，保留未知关系不能直接当作NONE的关键区别。','其中，KL散度衡量两个分布的差异，式（2-7）对两侧分布对称。将散度项加入学习目标，可约束原文与改写在可靠对应因素上的预测分布趋于接近。尚未确认的关系标签不参与相应监督和一致性项，也不直接改标为NONE。')
edit(283,'“分布接近”到三类学习目标的关系可更直接，末句罗列的定义需要落到用途。','先区分一致与正确，再说明为何分别处理三类目标，并连接第三章的受控比较。','避免把预测一致误读成效果保证，也明确基础公式在方法章中的用途。','分布接近反映的是对应因素上的预测一致程度，不能据此判断两侧预测都正确或完整图更准确。因此，本文分别设置原文整图生成监督、因素级辅助监督和成对约束。第三章将通过影响域、对应映射与审核掩码确定可参与学习的因素，再给出归一化目标，并在固定增强数据的条件下分析成对项的作用。')

edit(285,'公式前的说明以“形成完整I0的终态”收尾，流程顺序与阶段含义可更自然衔接。','从单次生成的不足引出候选，再按重排序、合法化、BR-O的执行顺序引入公式。','读者在见到符号前已知道式（2-8）描述哪个流程。','单次生成可能遗漏组件或产生错误关系，多候选方法通过生成若干备选结构扩大选择范围。设完整图候选集合为 S，重排序函数为 Erank。系统先选取得分最高的候选图，再执行各方法共用的合法化过程和继承的BR-O有界修正，得到完整I0流程的最终图：')
edit(287,'一段同时解释三个图状态、失败出口、金标限制和追加修正配置，读者容易混淆I1与最后一步算子。','按状态演进逐一解释符号，将失败规则和新增阶段放在对应操作后面。','更容易顺着公式识别各状态，明确完整推理配置与追加算子的包含关系。','其中，LA 为各方法共用的确定性合法化过程，其修改须保留记录。Grank是重排序得分最高的候选图，Gpre是合法化后、尚未执行BR-O的图。BR-O按继承协议执行并完成合法性复核，所得图记为G0；若未能形成合法G0，则记录初始化失败。合法化与BR-O均不使用测试金标选择修改。第四章将从G0开始的依赖闭合追加修正记为R_DC。推理配置I1包含完整I0及R_DC，而R_DC仅指追加修正算子。')
edit(288,'候选范围、影响域、三类误差来源和Oracle限制集中于一段，需明确它们的逻辑先后。','先说明候选如何限定修正范围，再区分覆盖、评分、搜索，并将Oracle限定紧贴用途。','读者可以定位遗漏发生在哪个环节，避免把搜索器无法恢复候选外对象误认为求解失败。','第四章在获得I0终态G0后，构建并冻结跨度集合 U、带类型组件集合 V 和关系候选集合 P，合称候选宇宙。这些有限集合限定了修正器能够到达的范围，“完整影响域”也在该范围内定义。候选覆盖、评分质量和预算内搜索分别影响最终选择：正确对象未进入候选时，求解器无法恢复它；对象已进入候选时，仍可能因评分或搜索限制而未被选中。离线Oracle分析可借助金标考察候选上界，但其信息不参与测试决策。')
edit(289,'两种分数的区别已存在，但“回答的是……”和随后判断条件之间可以更紧凑。','将给定跨度的类别判断与预测对象的完整正确性判断直接对照。','为训练辅助头和推理评分器不能共用分数提供清楚理由。','对象评分应与最终评价单位一致。给定金标跨度时，组件类别概率用于判断已知片段属于哪一类；对模型预测组件的完整正确性评分，还须判断其字符边界是否准确。关系评分则须同时考虑全部端点、类型、方向和标签。因此，训练辅助头的输出不能直接用作推理阶段的完整对象分数。')
edit(290,'校准例子的语序较绕，概率、合法性与F1的区别容易被读成一般性提醒。','直接给出校准要检查的对应关系，再用具体反例区分三个评价维度。','读者可据此判断校准结果能够支持什么结论，而不会将其等同于修正收益。','概率校准用于检查模型置信度与经验正确率的对应关系[45]。例如，在相同样本条件下，可检查评分接近0.8的一组对象是否约有80%正确。概率质量、结构合法性和最终F1衡量的内容不同：合法图仍可能包含错误关系，校准较好的概率也不保证任意搜索策略都能提高F1。针对F1的决策还需考虑对象集合与评价条件[41][42]。')
edit(291,'评分器的数据用途划分和高分选择带来的过程风险，连接尚可更直接。','先交代拟合数据来源，再指出为何还须检查实际接受轨迹。','说明总体校准和轨迹误改是互补检查，减少泛泛的风险提醒。','本文使用交叉拟合产生的预测候选训练推理评分器，并分别安排拟合、校准与策略选择的数据。修正过程优先选择高分提案，因此除固定候选上的评分质量外，还需检查实际接受轨迹中的误改。总体校准指标不能替代这项过程检查。')
edit(292,'全局与局部比较的条件、候选扩大后的代价以及内部目标与外部指标的关系密集并列。','明确比较时需要交代的维度，并分别说明候选规模取舍与目标差异。','读者能够按条件评估求解方法，避免把内部效用提高直接解释为F1改善。','结构化决策从有限候选中选择满足约束的对象组合。全局优化和局部搜索采用不同的求解方式，比较时应交代候选范围、评分、可行域及预算是否一致。扩大候选空间可能提高覆盖，也可能增加评分和求解开销。即使搜索获得更高的内部效用，严格抽取F1也不一定提高。')
edit(295,'节末多次强调不能直接推出收益，语气偏防御且承接较松。','将本节职责与下一章内容接在一起，用一句明确的比较要求保留证据边界。','结束段更像方法基础的自然承接，同时没有把表达能力写成已验证收益。','本节确立候选与结构化决策的共用概念。第四章将在此基础上定义组件修改后的依赖处理、接受条件、编辑预算和超时返回。集合动作或局部求解是否带来额外收益，须通过相应受控比较判断，仅凭其可表达的修改类型无法确定。')

edit(299,'匹配条件与辅助指标的用途之间还可补足逻辑衔接，避免只形成规则列表。','先给严格匹配条件，再说明诊断指标与主指标各自承担的用途。','读者更容易理解为什么组件分类或二元边结果不能替代完整关系评价。','组件匹配要求同一文档中的字符区间与原生类型完全一致；关系匹配还要求完整源集合、目标、方向和标签一致。CDCP按完整多前提关系计数，不将其展开为二元边。边界F1、给定金标组件的关系分类等指标可辅助定位误差，但不能替代端到端严格关系F1。')
edit(300,'三个指标口径在一段中并列，差值单位与不可混比的原因可以更明确。','依次说明汇总方式、报告单位和不同任务指标的命名。','读者能分辨micro平均、百分点差值和跨域指标，降低数字比较的歧义。','micro-F1先汇总对象计数，再代入式（2-9），不同于逐文档F1或各类别F1的平均值。本文以百分制报告分数，以百分点报告方法间差值。域内细粒度Relation-F1与历史跨域无标签Link-F1的评价对象不同，因此分别命名，不直接对二者数值求差。')
edit(301,'匹配、去重、失败、标识异常和零分母规则连续铺陈，缺少操作主体。','分别以匹配、预处理、失败文档和记录异常为主语，明确每项规则的适用对象。','规则更便于逐项执行和查阅，失败样本与记录错误也不会被混作同一类处理。','匹配时，每个预测对象和金标对象均最多使用一次，多余重复预测计入FP。若统一预处理已执行去重，则同时报告原始重复率，并对所有方法使用相同规则。解析失败、超长失败或图验证失败的文档仍保留在评价集合中，按空预测处理，其金标对象计入FN，失败率单独报告。文档标识缺失或重复属于记录错误，不作为可忽略样本跳过。分母为零时按预先规定记为0，同时保留整数计数。')
edit(302,'“前者不能代替后者解释过程风险”需要回溯辨认指代，记录关联和过程保存之间的作用可更具体。','点明跨章复用同一记录的用途，并直接区分最终净变化和逐次决策轨迹。','说明保存两类记录各自解决什么问题，减少抽象的“保持一致”表述。','所有结果通过语料、文档标识、训练种子和方法标识关联。同一配置跨章复用时，应引用同一份逐文档记录，使训练主表、推理主表和两阶段四种配置的结果表采用一致计数。最终图的净变化与修正中每次接受或拒绝的记录分别保存；过程风险须结合逐次决策记录分析，不能仅由最终净变化解释。')
edit(303,'本段再次完整介绍I0/I1，但它位于评价小节，读者需要更快找到阶段计数和成本归属。','保留必要定义，以评价中的状态区别为切入，再突出四种配置的出发点和追加成本记录。','将重复定义转为评价规则提醒，明确哪些图可进入I0结果以及完整时延包括哪些阶段。','评价中的I0指继承MCR-BR的完整推理配置，包括多候选生成与重排序、共同合法化和BR-O有界修正，其最终合法图记为G0。Gpre仅指重排序后经共同合法化、尚未执行BR-O的图，不计作I0结果。I1在完整I0之后追加依赖闭合修正R_DC，最终图为R_DC作用于G0后的返回结果。四种配置中的T0I1与T1I1，分别以相同训练配置的I0终态为起点。追加调用和编辑单独计数，完整推理时延则同时计入继承阶段与追加阶段。')

edit(308,'数据异常记录与坐标评价原则之间的衔接可更直接，“固定协议”较抽象。','说明记录存放位置后，将坐标映射和异常检查分别对应到评价身份与处理协议。','保留异常对象的原则更明确，也更容易找到相关复查材料。','训练去重、首尾空白处理及24个词中边界组件的记录见补充说明S2.2和附录A。坐标处理始终保留到原文的映射，评价沿用2.1节定义的字符身份。数据异常检查用于确定处理协议，不用于删除难以预测的测试对象。')
edit(309,'交叉拟合、三类数据用途、最终生成器和评分器的用数限制集中在长段中，角色切换频繁。','按分组、留出候选生成、评分器数据划分和最终用数边界的顺序展开，保持全部数量和不重叠条件。','读者能沿着数据流判断每类文档由哪个模块使用，更容易辨认隔离条件。','三折交叉拟合以源文档为分组单位，原文及其全部增强视图始终处于同一组。留出文档的候选由未使用该源文档训练的生成器产生。评分器拟合、校准和策略选择分别使用互不重叠的源文档：AAEC为255、32和32篇，CDCP为464、58和58篇。最终生成器可使用完整训练侧数据，但评分器拟合不再纳入校准与策略选择所用的标签。测试集不参与增强、校准或策略选择。')
edit(310,'主实验共享项、候选生成方式和自由预测数量规则堆在一起，比较口径需要更清楚。','先交代共享条件和种子，再说明候选生成、数量规则及对照配置。','读者可直接区分所有方法共用的条件与跨骨干分析所在位置。','主实验共用Qwen3.5-9B、训练预算、候选协议和严格评价器，训练种子为17、29和43。多候选由一路贪心生成和两路采样生成组成，预测对象数量自由，不按测试金标数量截断或补齐。同骨干对照采用相同基础条件，ICIC/MCR-BR基线T0也按当前骨干重新配置。跨骨干的四种配置比较见5.5节。')
edit(312,'“两类比较”的指代距离较远，学习目标对照、数据构造对照和推理策略对照的区别可进一步理顺。','逐项说明固定什么、变化什么，并将训练变化可能改变候选质量这一点放在推理对照之前。','读者更容易判断每组比较能够归因到哪一环节，而非笼统理解为控制了全部条件。','NoPair、CompPair与完整成对配置使用相同的增强视图、因素掩码和辅助头，比较主要反映学习目标的变化。数据构造对照则匹配接受规模与源文档更新预算。训练配置改变后，模型产生的候选质量也可能变化；比较同一训练检查点下的推理策略时，候选和评分须保持固定。因此，训练比较与推理比较应分别说明其控制条件。')
edit(313,'成本类别虽然齐全，但一次性准备与逐文档消耗的分界以及等预算含义可更顺畅。','用两类成本组织段落，再连接共享成本、失败消耗和等预算限制。','读者能判断费用计入哪里，并避免把token相同误读为运行时延相同。','计算成本分为两类：增强、审核、交叉拟合和评分器训练等一次性准备成本，以及逐文档的生成、提案、评分和求解成本。共享准备成本只计一次，拒绝、失败和超时产生的消耗均计入实际成本。等预算重生成同时匹配追加模型调用数与输入、输出token上限，CPU求解开销单独列出；相同token预算并不必然对应相同的端到端时延。')
edit(314,'统计汇总、记录字段和配对前提压在同一长句链中，“才能”之前条件较长。','按单种子计算、跨种子报告、逐文档记录和配对条件分层表达。','读者能明确micro-F1如何汇总，哪些字段和一致性条件支撑配对比较。','统计分析先按训练种子汇总全部测试文档的整数计数，计算各自的micro-F1，再报告三个种子的均值与样本标准差。逐文档记录至少包含语料、文档标识、源文档组、种子、方法、对象族、TP、FP、FN及失败状态。配对比较要求各方法使用相同的文档和种子，且同一任务下的金标对象总数 TP+FN 保持一致。')
edit(315,'联合重采样的步骤与补充区间的用途连在一起，读者不易快速抓住抽样共享和重新计数两个要点。','依照抽样、组处理、重新计数、形成差值分布的顺序叙述，再说明补充分析用途。','统计流程可以按步骤复述，共用抽样索引与不同不确定性来源更加清楚。','联合重采样执行2000次。每次有放回抽取3个种子，并独立抽取与原测试集文档数相同的文档索引，所有方法共用本次抽样结果。若文本存在重复组，则改以源文档组为抽样单位，保留组内全部文档。每次抽样后重新汇总TP、FP、FN，计算所抽种子的micro-F1及其平均值，由此形成方法差值的重采样分布。此外，分别报告三个种子的配对差值，以及固定种子、仅重采样文档的区间，用于区分不同来源的不确定性。')
edit(318,'比较族、校正方法和区间解释聚集在同一段，最后一句再次概括前面已讲明的区别。','先明确主要比较族及其定位，再紧邻解释Holm校正p与单项区间为何可能给出不同表象。','读者不会将单项区间与家族校正检验混为一谈，段末也减少重复提醒。','主要比较族包括7组严格关系F1比较，每组在2种语料上检验，共14项，分别考察训练配置、成对项、推理配置、组件修改范围、共同接受、等预算重生成和开发风险限制。具体方法对及归因边界见补充表S2-4。14项p值统一采用Holm方法调整，单项95%区间则未作家族同时校正。由于二者对应的统计判断不同，单项区间不含零与校正p大于0.05可以同时出现。')
edit(319,'复算材料、跨表一致和种子不确定性混合叙述，最后的“条件限定”可更具体。','先列明共同输入和生成表格，再说明三个种子能覆盖的变化范围。','读者能定位复算依赖，并理解不确定性范围，而不是只读到笼统谨慎用语。','统计包保存了文档×种子×方法的完整整数计数、14项比较族、2000次共同抽样索引及各项复算输出。表3-6、表4-6和表5-3均由这些共同输入生成，相同方法在训练表与推理表中的重复行逐项一致。三个种子只能反映有限的种子差异，所得区间仍须在本实验条件下解释。复算材料说明见附录J的S2.5。')

edit(321,'“上述理论分别服务于……”偏概括，训练和推理的输入对象与处理对象可直接作为主线。','分别说明两阶段读取什么、处理什么，并把原文保持不变的限制贴近推理操作。','总体图出现前，读者已明确两阶段数据流和操作对象的区别。','训练与推理使用不同的输入和监督条件。训练阶段读取带标注的原文，构造局部改写，并判断哪些因素监督可以保留。推理阶段读取未提供金标的新文档，保持原文不变，对预测组件和关系进行选择与修正。图2-1展示两阶段的数据流。')
edit(324,'辅助头和评分器的来源、输入、停用阶段及更新关系集中排列，读者容易误以为两者输出可互用。','按训练监督、辅助头的使用边界、推理评分器的职责顺序说明，明确两个模块的接口差别。','更容易判断测试时哪些模块实际存在、哪些分数用于结构决策。','原文提供完整图生成监督，增强视图只在通过审核的因素上参与辅助监督和一致性学习。训练辅助头使用金标跨度定位监督对象，但不将待预测的类型和关系标签作为输入，并在开发评价与测试时移除。推理评分器则在交叉拟合候选上学习完整对象正确性，其输出独立用于结构决策。两者不直接共用概率，推理评分器也不回传更新生成器。')
edit(325,'“每个阶段保留自己的出口”带有工程口语，章节分工和共同评价规则之间可衔接得更清楚。','保留继承与新增工作的分工，用规范的处理规则说明各阶段的拒绝和失败记录。','段落既能承接后文，也明确不同阶段共享身份和计数规则，而不暗示共享全部机制。','结论专项建模、多候选生成和初始重排序沿用MCR-BR。第三章研究关系影响域与可靠因素学习，第四章研究组件修改后的依赖处理和接受决策，第五章分析两阶段组合的作用。各阶段保留各自的拒绝或失败处理分支，评价统一采用本章定义的完整对象身份与计数规则。')
edit(327,'小结按“介绍了哪些技术”回放内容，对这些基础如何连接两项工作总结不足。','以对象身份、学习与决策分工、共同评价条件三个实际用途收束，再自然引出方法章。','读者更容易带着共同定义进入第三、四章，不必再读一遍目录式技术清单。','本章以文档、字符半开区间和原生类型确定组件身份，并以完整端点表示二元及多前提关系，统一了训练与推理所用的论辩对象。预训练模型与参数高效适配提供生成基础，数据增强与因素一致性学习组织训练监督，候选评分和结构化决策负责对象选择。严格匹配、公共数据条件与配对统计规则为后续比较确立共同口径。第三章据此研究改写后的监督保持，第四章研究预测图的结构修正。')

for p in edits:
    idx=int(p['block_id'][1:])
    heads=[b for b in B.values() if b['index']<=idx and b['index']>=234 and b['style_name'].startswith('heading')]
    p['section']=heads[-1]['text'] if heads else '章首'
assert len({p['block_id'] for p in edits})==len(edits)
(O/'_work/patches.json').write_text(json.dumps(edits,ensure_ascii=False,indent=2))
(O/'_work/revised_scope.txt').write_text('\n\n'.join(f'[{p["block_id"]}] {p["section"]}\n{p["new_text"]}' for p in edits))
print(json.dumps({'paragraphs':len(edits),'sections':dict(Counter(p['section'] for p in edits))},ensure_ascii=False))
